using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.Text.RegularExpressions;
using WF=System.Windows.Forms;
namespace PhotoTutor {
 internal sealed class InlineMathRow:WF.Control {
  sealed class Run{internal string Text="";internal Bitmap? Image;internal Rectangle Box;}
   readonly List<Run> runs=new List<Run>();readonly int rasterDpi;readonly Font pixelFont;readonly Bitmap measureSurface=new Bitmap(1,1);readonly Graphics measureGraphics;readonly StringFormat textFormat=(StringFormat)StringFormat.GenericTypographic.Clone();bool layingOut;
   internal InlineMathRow(int width,Font font,string source,int dpi=96){DoubleBuffered=true;BackColor=Color.White;ForeColor=Color.FromArgb(25,35,45);Font=font;rasterDpi=dpi;pixelFont=new Font(font.FontFamily,font.SizeInPoints*dpi/72,font.Style,GraphicsUnit.Pixel);measureGraphics=Graphics.FromImage(measureSurface);textFormat.FormatFlags|=StringFormatFlags.MeasureTrailingSpaces;Width=width;AccessibleName=source;Margin=new WF.Padding(0,3,0,12);}
   internal void AddText(string value){var word=new System.Text.StringBuilder();Action flush=()=>{if(word.Length==0)return;string text=word.ToString();word.Clear();if(Measure(text).Width<=Math.Max(20,Width)){runs.Add(new Run{Text=text});return;}foreach(string element in TextElements.Split(text))runs.Add(new Run{Text=element});};foreach(string element in TextElements.Split(value)){bool ascii=element.Length==1&&((element[0]>='A'&&element[0]<='Z')||(element[0]>='a'&&element[0]<='z')||(element[0]>='0'&&element[0]<='9'));if(ascii){word.Append(element);continue;}flush();runs.Add(new Run{Text=element,Image=IsMathElement(element)?GlyphBitmap(element):null});}flush();}
  internal void AddMath(Bitmap bitmap)=>runs.Add(new Run{Image=bitmap});
   internal static bool HasMathGlyph(string text)=>IsMathElement(text);
   static bool IsMathElement(string text){for(int i=0;i<text.Length;i++){if(text[i]>='\u20d0'&&text[i]<='\u20ff')return true;if(char.IsHighSurrogate(text[i])&&i+1<text.Length&&char.IsLowSurrogate(text[i+1])){int code=char.ConvertToUtf32(text,i);if(code>=0x1d400&&code<=0x1d7ff)return true;}}return false;}
   Bitmap GlyphBitmap(string text){double em=Font.SizeInPoints*rasterDpi/72;char accent=text[text.Length-1];bool arrow=text.Length>1&&(accent=='\u20d6'||accent=='\u20d7'||accent=='\u20e1');if(arrow)text=text.Substring(0,text.Length-1);var formatted=new System.Windows.Media.FormattedText(text,CultureInfo.InvariantCulture,System.Windows.FlowDirection.LeftToRight,new System.Windows.Media.Typeface("Cambria Math"),em,System.Windows.Media.Brushes.Black,1);var geometry=formatted.BuildGeometry(new System.Windows.Point());var bounds=geometry.Bounds;double top=arrow?Math.Max(6,em*.23):0;var visual=new System.Windows.Media.DrawingVisual();using(var drawing=visual.RenderOpen()){drawing.PushTransform(new System.Windows.Media.TranslateTransform(2-bounds.X,2-bounds.Y+top));drawing.DrawGeometry(System.Windows.Media.Brushes.Black,null,geometry);drawing.Pop();if(arrow){var pen=new System.Windows.Media.Pen(System.Windows.Media.Brushes.Black,Math.Max(1,em*.035));double left=2,right=Math.Max(left+em*.35,bounds.Width+2),y=2+top*.35,head=Math.Max(3,em*.12);drawing.DrawLine(pen,new System.Windows.Point(left,y),new System.Windows.Point(right,y));if(accent!='\u20d6'){drawing.DrawLine(pen,new System.Windows.Point(right,y),new System.Windows.Point(right-head,y-head*.55));drawing.DrawLine(pen,new System.Windows.Point(right,y),new System.Windows.Point(right-head,y+head*.55));}if(accent!='\u20d7'){drawing.DrawLine(pen,new System.Windows.Point(left,y),new System.Windows.Point(left+head,y-head*.55));drawing.DrawLine(pen,new System.Windows.Point(left,y),new System.Windows.Point(left+head,y+head*.55));}}}var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(Math.Max(1,(int)Math.Ceiling(Math.Max(bounds.Width,arrow?em*.35:0))+4),Math.Max(1,(int)Math.Ceiling(bounds.Height+top)+4),96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(visual);return Raster.ToBitmap(bitmap);}
   Size Measure(string text){var size=measureGraphics.MeasureString(text,pixelFont,int.MaxValue,textFormat);return new Size((int)Math.Ceiling(size.Width),(int)Math.Ceiling(size.Height));}
  internal void Reflow(){if(layingOut||IsDisposed||pixelFont==null)return;layingOut=true;try{int baseHeight=(int)Math.Ceiling(pixelFont.GetHeight(measureGraphics));int y=0,x=0,lineHeight=baseHeight;var line=new List<Run>();Action finish=()=>{foreach(var r in line){var b=r.Box;b.Y=y+(lineHeight-b.Height)/2;r.Box=b;}y+=lineHeight+2;x=0;lineHeight=baseHeight;line.Clear();};foreach(var r in runs){var size=r.Image?.Size??Measure(r.Text);if(x>0&&x+size.Width>Width)finish();r.Box=new Rectangle(x,y,size.Width,size.Height);x+=size.Width;lineHeight=Math.Max(lineHeight,size.Height);line.Add(r);}if(line.Count>0)finish();Height=Math.Max(baseHeight,y);Invalidate();}finally{layingOut=false;}}
  protected override void OnSizeChanged(EventArgs e){base.OnSizeChanged(e);Reflow();}
   protected override void OnPaint(WF.PaintEventArgs e){base.OnPaint(e);using(var brush=new SolidBrush(ForeColor))foreach(var r in runs){if(r.Image!=null)e.Graphics.DrawImageUnscaled(r.Image,r.Box.Location);else e.Graphics.DrawString(r.Text,pixelFont,brush,r.Box.Location,textFormat);}}
   protected override void Dispose(bool disposing){if(disposing){foreach(var r in runs)r.Image?.Dispose();runs.Clear();measureGraphics.Dispose();measureSurface.Dispose();pixelFont.Dispose();textFormat.Dispose();}base.Dispose(disposing);}
 }
}
